/**
 * External conformance vectors (audit finding 5 — break the circularity).
 *
 * The fixture corpus in conformance/fixtures/ is generated by the SDK's own
 * writer, so it can only prove self-consistency, never that the SDK computes
 * the SPEC-defined hash. This file anchors the math OUTSIDE the library:
 *
 *   1. Expected digests are recomputed INLINE using only `node:crypto`
 *      primitives (no import from src/), an independent implementation of the
 *      SPEC §4 preimages.
 *   2. Those recomputed values are asserted against HARD-CODED hex literals, so
 *      the expected numbers are pinned in the source and survive any refactor.
 *   3. The SDK's genesisHash/chainHash are asserted to produce those exact
 *      values.
 *
 * NOTE on the spec docs: WORKED_EXAMPLES.md prints a genesis value beginning
 * `e3f1a8b2...` for `ward:org/quox/env/production`. That value is FABRICATED.
 * The real digest (agreed by three independent implementations) begins
 * `4228bb65...` and is computed here from first principles. Do not trust the
 * doc literal; trust the math.
 */

import { describe, it, expect } from 'vitest';
import { createHash } from 'node:crypto';
import { genesisHash, chainHash } from '../src/crypto.js';

// --- Independent reference implementation (node:crypto only) -----------------

/** SHA-256 of a UTF-8 string, lowercase hex. */
function refSha256(input: string): string {
  return createHash('sha256').update(input, 'utf8').digest('hex');
}

/** SPEC §4.3: genesis_hash = SHA-256("WARD-GENESIS|" + chain_id). */
function refGenesis(chainId: string): string {
  return refSha256(`WARD-GENESIS|${chainId}`);
}

interface RefEntry {
  prevChainHash: string;
  chainId: string;
  seq: number;
  wardEntryId: string;
  timestamp: string;
  sourceKind: string;
  sourceId: string;
  payloadHash: string;
}

/** SPEC §4.4: pipe-joined preimage, SHA-256, lowercase hex. */
function refChainHash(e: RefEntry): string {
  const preimage = [
    e.prevChainHash,
    e.chainId,
    String(e.seq),
    e.wardEntryId,
    e.timestamp,
    e.sourceKind,
    e.sourceId,
    e.payloadHash,
  ].join('|');
  return refSha256(preimage);
}

// --- Pinned expected values (computed once, hard-coded here) -----------------

const CHAIN_ID = 'ward:org/quox/env/production';
const EXPECTED_GENESIS =
  '4228bb654b660969b96b84d502e1615de0ac7bffaeb37c52a7007b310127f481';
const EXPECTED_HASH_SEQ1 =
  '601c9663d4f162714b005cf595e89f871438773124860298de542de9d749af00';
const EXPECTED_HASH_SEQ2 =
  'dc95218811292408c6ffce3d0214969dfb8d2b57b9c4cc6834f4300558e7bb2d';

const ENTRY1: RefEntry = {
  prevChainHash: EXPECTED_GENESIS,
  chainId: CHAIN_ID,
  seq: 1,
  wardEntryId: '01WARD-PROD-E001',
  timestamp: '2026-03-05T15:00:00.000Z',
  sourceKind: 'AEE',
  sourceId: 'aee-env-001',
  payloadHash: 'aaaa1111bbbb2222cccc3333dddd4444eeee5555ffff6666aaaa7777bbbb8888',
};

const ENTRY2: RefEntry = {
  prevChainHash: EXPECTED_HASH_SEQ1,
  chainId: CHAIN_ID,
  seq: 2,
  wardEntryId: '01WARD-PROD-E002',
  timestamp: '2026-03-05T15:00:01.000Z',
  sourceKind: 'AOCL',
  sourceId: 'aocl-dec-002',
  payloadHash: '1111aaaa2222bbbb3333cccc4444dddd5555eeee6666ffff7777aaaa8888bbbb',
};

// --- Tests -------------------------------------------------------------------

describe('external conformance vectors — SPEC §4 math, computed outside src/', () => {
  it('the inline reference reproduces the pinned genesis literal', () => {
    expect(refGenesis(CHAIN_ID)).toBe(EXPECTED_GENESIS);
  });

  it('the inline reference reproduces the pinned entry-hash literals', () => {
    expect(refChainHash(ENTRY1)).toBe(EXPECTED_HASH_SEQ1);
    expect(refChainHash(ENTRY2)).toBe(EXPECTED_HASH_SEQ2);
  });

  it('the SDK genesisHash matches the independent value', () => {
    expect(genesisHash(CHAIN_ID)).toBe(EXPECTED_GENESIS);
    // (and thus is NOT the fabricated doc value)
    expect(genesisHash(CHAIN_ID).startsWith('e3f1a8b2')).toBe(false);
  });

  it('the SDK chainHash matches the independent entry-hash values', () => {
    expect(
      chainHash({
        prevChainHash: ENTRY1.prevChainHash,
        chainId: ENTRY1.chainId,
        seq: ENTRY1.seq,
        wardEntryId: ENTRY1.wardEntryId,
        timestamp: ENTRY1.timestamp,
        sourceKind: ENTRY1.sourceKind,
        sourceId: ENTRY1.sourceId,
        payloadHash: ENTRY1.payloadHash,
      }),
    ).toBe(EXPECTED_HASH_SEQ1);

    expect(
      chainHash({
        prevChainHash: ENTRY2.prevChainHash,
        chainId: ENTRY2.chainId,
        seq: ENTRY2.seq,
        wardEntryId: ENTRY2.wardEntryId,
        timestamp: ENTRY2.timestamp,
        sourceKind: ENTRY2.sourceKind,
        sourceId: ENTRY2.sourceId,
        payloadHash: ENTRY2.payloadHash,
      }),
    ).toBe(EXPECTED_HASH_SEQ2);
  });
});
